preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Pen+Script&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: .9rem .75rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtlta-font-size로 바꿉니다. */
.rtlta {
  --rtlta-bg-fill: transparent;
  --rtlta-blur: none;
  --rtlta-bg-edge: none;
  --rtlta-font-body: "Gowun Batang", "Noto Serif KR", serif;
  --rtlta-font-display: "Nanum Pen Script", "Gowun Batang", cursive;
  --rtlta-font-size: 16px;
  --rtlta-line-height: 1.9;
  --rtlta-para-gap: 0;
  --rtlta-dialog-weight: 700;
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtlta {
  --risu-font-family: var(--rtlta-font-body);
  --FontColorStandard: var(--rtlta-ink);
  --FontColorBold: var(--rtlta-ink);
  --FontColorItalic: var(--rtlta-muted);
  --FontColorItalicBold: var(--rtlta-muted);
  --FontColorQuote1: var(--rtlta-muted);
  --FontColorQuote2: var(--rtlta-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtlta-ink);
  font-family: var(--rtlta-font-body);
  font-size: var(--rtlta-font-size);
  line-height: var(--rtlta-line-height);
}
.rtlta, .rtlta *, .rtlta *::before, .rtlta *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtlta.rtlta { display: block; }
.rtlta__content {
  min-width: 0;
  color: var(--rtlta-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtlta__content .chattext {
  --tw-prose-code: var(--rtlta-ink);
  --tw-prose-pre-code: var(--rtlta-ink);
  --tw-prose-pre-bg: var(--rtlta-tint);
  max-width: none;
  color: var(--rtlta-ink);
  font-size: var(--rtlta-font-size) !important;
  line-height: var(--rtlta-line-height) !important;
}
.rtlta__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtlta-font-size);
  line-height: var(--rtlta-line-height);
}
.rtlta__content p { margin: 0 0 var(--rtlta-para-gap); }
.rtlta__content p:last-child { margin-bottom: 0; }
.rtlta__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtlta-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtlta-ink);
  font-family: var(--rtlta-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtlta__content h1 { font-size: calc(var(--rtlta-font-size) * 1.6); }
.rtlta__content h2 { font-size: calc(var(--rtlta-font-size) * 1.35); }
.rtlta__content h3 { font-size: calc(var(--rtlta-font-size) * 1.15); }
.rtlta__content :is(h4, h5, h6) { font-size: var(--rtlta-font-size); }
.rtlta__content strong { font-weight: 700; }
.rtlta__content em { color: var(--rtlta-muted); }
.rtlta__content mark[risu-mark="quote1"],
.rtlta__content mark[risu-mark="blockquote1"] { color: var(--rtlta-muted); background: transparent; }
.rtlta__content mark[risu-mark="quote2"],
.rtlta__content mark[risu-mark="blockquote2"] {
  color: var(--rtlta-dialog);
  font-weight: var(--rtlta-dialog-weight);
  background: transparent;
}
.rtlta__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtlta-line);
  color: var(--rtlta-muted);
}
.rtlta__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtlta__content li { margin: .25em 0; color: var(--rtlta-ink); }
.rtlta__content li::marker { color: var(--rtlta-muted); }
.rtlta__content a { color: var(--rtlta-accent); text-decoration: underline; }
.rtlta__content hr { border: 0; border-top: 1px solid var(--rtlta-line); margin: 1.5em 0; }
.rtlta__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtlta-ink);
  background: var(--rtlta-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtlta-font-size) * .88);
}
.rtlta__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtlta-ink);
  background: var(--rtlta-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtlta-font-size) * .88);
  line-height: 1.5;
}
.rtlta__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtlta__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtlta__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtlta-ink);
  border-bottom: 1px solid var(--rtlta-line);
  text-align: left;
  vertical-align: top;
}
.rtlta__content th { font-weight: 700; }
.rtlta__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtlta__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtlta-ink) !important;
  background: var(--rtlta-edit-bg) !important;
  border: 1px solid var(--rtlta-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtlta-font-size) !important;
  line-height: var(--rtlta-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtlta__footer {
  --risu-theme-textcolor2: var(--rtlta-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtlta__info, .rtlta__actions { min-width: 0; max-width: 100%; }
.rtlta__info > div, .rtlta__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtlta__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtlta__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtlta__footer button:hover { background: var(--rtlta-tint); }
.rtlta :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtlta-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtlta__portrait { overflow: hidden; background: var(--rtlta-tint); }
.rtlta__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtlta__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtlta-bg-fill);
  -webkit-backdrop-filter: var(--rtlta-blur);
  backdrop-filter: var(--rtlta-blur);
  box-shadow: var(--rtlta-bg-edge);
}

/* 구조: 편지 한쪽 */

.rtlta {
  max-width: 46rem;
  margin: 0 auto;
  padding: 1.3rem clamp(1.1rem, 4vw, 2.2rem) 1rem;
  background-color: var(--rtlta-paper);
  background-image: repeating-linear-gradient(to bottom, transparent 0, transparent calc(var(--rtlta-font-size) * var(--rtlta-line-height) - 1px), var(--rtlta-rule) calc(var(--rtlta-font-size) * var(--rtlta-line-height) - 1px), var(--rtlta-rule) calc(var(--rtlta-font-size) * var(--rtlta-line-height)));
  background-position: 0 calc(1.3rem + var(--rtlta-stamp-h) + .8rem);
  border-radius: .25rem;
  box-shadow: 0 1px 3px var(--rtlta-shadow), 0 10px 26px var(--rtlta-shadow);
}
.rtlta__head { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; min-height: var(--rtlta-stamp-h); margin-bottom: .8rem; }
.rtlta__from { align-self: flex-end; font-family: var(--rtlta-font-display); font-size: 1.7em; line-height: 1.1; color: var(--rtlta-ink); }
.rtlta__from-label { font-size: .7em; color: var(--rtlta-muted); }
/* 우표 초상: 오른쪽 위 */
.rtlta__frame {
  flex: 0 0 auto;
  width: var(--rtlta-stamp-w);
  aspect-ratio: 3 / 4;
  padding: 5px;
  background: var(--rtlta-stamp);
  outline: 4px dotted var(--rtlta-paper);
  outline-offset: -2px;
  box-shadow: 0 3px 10px var(--rtlta-shadow);
  transform: rotate(2deg);
}
.rtlta__portrait { width: 100%; height: 100%; }
.rtlta__footer { margin-top: .7rem; font-family: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif; font-size: .8em; }
.rtlta__content :is(h1, h2, h3, h4, h5, h6) { --risu-font-family: var(--rtlta-font-body); font-family: var(--rtlta-font-body); }
.rtlta { --rtlta-stamp-w: clamp(3.8rem, 9vw, 5.2rem); --rtlta-stamp-h: calc(var(--rtlta-stamp-w) * 4 / 3); }
/* 사용자의 답장: 오른쪽에 붙는 작은 쪽지 */
.rtlta--user { max-width: 32rem; background-color: var(--rtlta-paper-user); }
.rtlta.rtlta--user { margin: 0 max(0px, calc((100% - 46rem) / 2)) 0 auto; }
@media (max-width: 520px) { .rtlta { --rtlta-stamp-w: 3.6rem; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (크라프트지) ── */
.rtlta {
  --rtlta-paper: #d8c29f;
  --rtlta-paper-user: #cfb791;
  --rtlta-rule: #c4ab84;
  --rtlta-ink: #33261a;
  --rtlta-muted: #6e5940;
  --rtlta-accent: #6f4426;
  --rtlta-dialog: #5a3418;
  --rtlta-stamp: #f4ead8;
  --rtlta-shadow: rgba(60, 40, 15, .2);
  --rtlta-line: #bea47c;
  --rtlta-tint: #cdb68f;
  --rtlta-edit-bg: #e6d5b8;
}
